const input = $json.body ?? $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || `req_${executionId}`;
const payload = input.live_probe || input;
const isProbe = payload.intent === 'live_probe' || input.intent === 'live_probe';
const skillId = payload.input?.skill_id || input.input?.skill_id || 'project-management-support-steering';
const capabilities = payload.context?.expected_capabilities || input.context?.expected_capabilities || [
  'approved_skill_validation',
  'internal_skill_orchestrator_boundary',
  'actor_twin_checkpoint',
  'approval_gate_detection',
  'trace_response'
];
const riskyActionDetected = isProbe || /send|email|meeting|calendar|invite|external/i.test(JSON.stringify(payload.input || input.input || {}));

const response = riskyActionDetected ? {
  envelope_version: input.envelope_version || payload.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'agentic_butler',
  status: 'approval_required',
  approval: {
    required: true,
    gate: 'requires_human_action',
    summary: 'The skill run reaches a human approval boundary before any external action.',
    proposed_action: 'Prepare the skill output and pause before sending messages, creating meetings, or writing to external systems.'
  },
  output: {
    readiness: 'connected',
    side_effects: 'none',
    skill_id: skillId,
    capabilities_checked: capabilities,
    approval_queue: [
      {
        gate: 'requires_human_action',
        action: 'external_action_blocked',
        status: 'pending_human_approval'
      }
    ]
  },
  trace: {
    stored: true,
    trace_id: `n8n_exec_${executionId}`,
    used_agents: ['agentic_butler_shell', 'skill_orchestrator_internal_boundary', 'actor_twin_checkpoint_boundary']
  }
} : {
  envelope_version: input.envelope_version || payload.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'agentic_butler',
  status: 'completed',
  output: {
    summary: 'Daily plan generated from supplied source context.',
    todos: [
      {
        what: 'Prepare alignment brief',
        how: 'Summarize exported source context and list open decisions.',
        why: 'Reduces ambiguity and decision latency.',
        whom: 'Relevant workstream stakeholders',
        priority: 'high',
        comments: 'No external action executed.'
      }
    ],
    approval_queue: []
  },
  trace: {
    stored: true,
    trace_id: `n8n_exec_${executionId}`,
    used_agents: ['agentic_butler_shell', 'skill_orchestrator_internal_boundary']
  }
};

return [{ json: response }];
